from qq import q
q("""SELECT CargoSubType, COUNT(*) n, SUM(CAST(QuantityInBarrels AS bigint))/1000 kb FROM dbo.uvS_VoyagesSummary WHERE VesselClassID IN (84,85,86) AND FirstLoadPortSailingDate>='2026-06-01' AND FirstLoadPortSailingDate<GETUTCDATE() AND FirstLoadPortName='Fujairah' AND StsLoadInd=0 AND CargoGroup='Dirty' GROUP BY CargoSubType ORDER BY kb DESC""")
q("""SELECT DATEPART(month, FirstLoadPortSailingDate) m, COUNT(*) n, SUM(CAST(QuantityInBarrels AS bigint))/1000 kb FROM dbo.uvS_VoyagesSummary WHERE VesselClassID IN (84,85,86) AND FirstLoadPortSailingDate>='2026-01-01' AND FirstLoadPortSailingDate<GETUTCDATE() AND FirstLoadPortName='Fujairah' AND StsLoadInd=0 AND CargoGroup='Dirty' GROUP BY DATEPART(month, FirstLoadPortSailingDate) ORDER BY 1""")
q("""SELECT DATEPART(month, LastDischargePortArrivalDate) m, FirstLoadPortCountryName c, COUNT(*) n, SUM(CAST(QuantityInBarrels AS bigint))/1000 kb FROM dbo.uvS_VoyagesSummary WHERE VesselClassID IN (84,85,86) AND LastDischargePortArrivalDate>='2026-01-01' AND LastDischargePortArrivalDate<GETUTCDATE() AND LastDischargePortName='Fujairah' AND CargoGroup='Dirty' GROUP BY DATEPART(month, LastDischargePortArrivalDate), FirstLoadPortCountryName ORDER BY 1, kb DESC""")
q("""SELECT DATEPART(month, w.DayDate) m, COUNT(*) n, SUM(CAST(vs.QuantityInBarrels AS bigint))/1000 kb, SUM(CASE WHEN vs.LastDischargePortName='Fujairah' THEN CAST(vs.QuantityInBarrels AS bigint) ELSE 0 END)/1000 kb_to_fuj
FROM dbo.uvs_WaypointsTracking w JOIN dbo.uvs_VesselDataPerDayEnhanced d ON d.IMO=w.IMO AND d.DayDate=w.DayDate JOIN dbo.uvS_VoyagesSummary vs ON vs.VoyageID=d.VoyageID
WHERE w.WaypointID=18 AND w.Direction='WE' AND w.LoadingStateID=1 AND w.DayDate>='2026-01-01' GROUP BY DATEPART(month, w.DayDate) ORDER BY 1""")
